return {
  { lhs = "<leader>U", name = "Группа: TUI-утилиты", doc = "Группа утилит с терминальным интерфейсом. Каждая открывается в плавающем окне внутри Neovim, как Tele. Закрыть окно — клавиша ещё раз или q; процесс продолжает работать. Список — <leader>Uu." },
  { lhs = "<leader>Uu", name = "Меню всех TUI-утилит", doc = "Выбор утилиты списком. Перед названием: ✓ установлена, ✗ нет (тогда в описании/проверке — как поставить). Та же команда: :Tui." },
  { lhs = "<leader>Uh", name = "Проверка TUI-утилит", doc = "Показывает, какие утилиты установлены, для недостающих — команду установки, и заданы ли переменные подключений NVIM_REDIS_URL и NVIM_DB_PG. Та же команда: :TuiCheck." },
  { lhs = "<leader>Uk", name = "k9s — Kubernetes", doc = "TUI кластера Kubernetes: поды, deployments, сервисы, логи, контексты. Нужен kubeconfig. Клавиши внутри k9s: ? — справка, : — команды (например :pods), l — логи, d — описание, Esc — назад." },
  { lhs = "<leader>Ur", name = "iredis — Redis с автодополнением", doc = "Клиент Redis с подсветкой и автодополнением команд и ключей. Адрес: переменная NVIM_REDIS_URL (например redis://localhost:6379/0), иначе localhost:6379. Выход: exit или Ctrl-D. Поиск по истории — Ctrl-R." },
  { lhs = "<leader>Uc", name = "redis-cli — Redis классический", doc = "Стандартный клиент Redis (из пакета redis). Адрес — NVIM_REDIS_URL. Пример команды: KEYS *, GET key, HGETALL key. Выход: exit." },
  { lhs = "<leader>Up", name = "pgcli — PostgreSQL с автодополнением", doc = "psql с автодополнением таблиц и колонок и подсветкой. Адрес — NVIM_DB_PG (та же переменная, что у <leader>Dp). Команды: \\dt (таблицы), \\d имя (описание), \\q (выход)." },
  { lhs = "<leader>Ul", name = "lazysql — TUI-клиент БД", doc = "Клиент баз данных в терминальном окне: PostgreSQL, MySQL, SQLite, MSSQL. Подключения добавляются внутри: a — добавить, e — изменить (в списке подключений). Ctrl+e — SQL-редактор. F10 — проверка обновлений. Хранятся в конфиге lazysql (~/.config/lazysql)." },
  { lhs = "<leader>Ud", name = "lazydocker — Docker", doc = "TUI Docker: контейнеры, логи, образы, тома, сети. Клавиши показаны внизу окна." },
  { lhs = "<leader>Ui", name = "dive — слои Docker-образа", doc = "Показывает, из каких слоёв состоит образ и сколько места занимает каждый. Спросит имя образа (например myapp:latest). Tab — переключить слои и дерево файлов, Q или Ctrl-C — выход." },
  { lhs = "<leader>Ub", name = "btop — монитор ресурсов", doc = "Процессы, загрузка CPU, память, диски, сеть в одном окне. Внутри: q — выход, F2 — настройки." },
  { lhs = "<leader>Ua", name = "ktea — Kafka TUI", doc = "Топики, consumer-группы, сообщения Kafka в терминальном окне. Нужен установленный ktea и адрес брокера в его настройках." },
}
